## Submitted testbench
```systemverilog
module tb;

  // Clock and reset
  logic clk;
  logic rst;

  // Configuration prescale (matches the regression setup)
  logic [15:0] preset = 16'd5;

  // AXI‑Stream driver signals
  logic [7:0] s_axis_tdata;
  logic       s_axis_tvalid;
  logic       s_axis_tready;
  logic       txd;
  logic       busy;

  // Instantiate the transmitter (uart_tx)
  uart_tx #(.DATA_WIDTH(8)) tx_dut (
    .clk          (clk),
    .rst          (rst),
    .s_axis_tdata (s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .txd          (txd),
    .busy         (busy),
    .prescale     (preset)
  );

  // Clock generation (approximately 100 MHz)
  initial clk = 0;
  always #10 clk = ~clk;

  // Reset sequence
  initial begin
    rst = 0;
    #200;
    rst = 1;
    #200;
    rst = 0;
    #200;
  end

  // Stimulus
  initial begin
    // Wait until reset is released and sample the first rising edge
    @(negedge rst);
    @(posedge clk);

    // Present a valid transaction with the first data byte (0xA5)
    s_axis_tvalid = 1'b1;
    s_axis_tdata  = 8'hA5;

    // Wait for the transmitter to finish the frame
    wait (busy == 1'b0);
    // Change to the second required byte (0x3C) while keeping tvalid high
    s_axis_tdata = 8'h3C;

    // Wait for the second frame to complete
    wait (busy == 1'b0);

    // Allow the coverage model to observe the required condition
    #500;
    $finish;
  end

endmodule
```

